def can_attend_meetings_brute(intervals):
    n = len(intervals)
    for i in range(n):
        for j in range(i + 1, n):                          # check every pair directly
            a, b = intervals[i], intervals[j]
            if a[0] < b[1] and b[0] < a[1]:
                return False
    return True

